 1→export type NaturalNote = 'C' | 'D' | 'E' | 'F' | 'G' | 'A' | 'B';
 2→
 3→export interface FretNote {
 4→  string: number;      // 1-6 (1 = high E, 6 = low E)
 5→  fret: number;        // 0-15 (0 = open)
 6→  note: NaturalNote;   // natural note name
 7→  x: number;           // x position on fretboard image (%)
 8→  y: number;           // y position on fretboard image (%)
 9→}
10→
11→/**
12→ * Chromatic scale used to derive natural notes per string.
13→ * Standard guitar tuning: E-A-D-G-B-E (string 6 to 1).
14→ */
15→const CHROMATIC_SCALE = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'] as const;
16→
17→const NATURAL_NOTES: ReadonlySet<string> = new Set<NaturalNote>(['C', 'D', 'E', 'F', 'G', 'A', 'B']);
18→
19→/** Open string notes in standard tuning, indexed by string number (1-6). */
20→const OPEN_STRING_NOTES: Record<number, NaturalNote> = {
21→  1: 'E', // high E
22→  2: 'B',
23→  3: 'G',
24→  4: 'D',
25→  5: 'A',
26→  6: 'E', // low E
27→};
28→
29→/**
30→ * Y-position (%) for each string on the fretboard image.
31→ * String 6 (low E) is at the bottom, string 1 (high E) at the top.
32→ */
33→const STRING_Y_POSITIONS: Record<number, number> = {
34→  1: 8,
35→  2: 25,
36→  3: 42,
37→  4: 58,
38→  5: 75,
39→  6: 92,
40→};
41→
42→/**
43→ * X-position (%) for each fret on the fretboard image.
44→ * Fret 0 (open/nut) is on the far left, fret 15 on the far right.
45→ * Positions approximate the midpoint of each fret space.
46→ */
47→function fretXPosition(fret: number): number {
48→  if (fret === 0) {
49→    return 1.5;
50→  }
51→  // Frets 1-15 distributed across roughly 6% to 97% of the image width
52→  // Real fretboard spacing decreases toward higher frets, but we use
53→  // approximate linear spacing since these will be fine-tuned later.
54→  return 3 + (fret / 15) * 94;
55→}
56→
57→function generateFretNotes(): FretNote[] {
58→  const notes: FretNote[] = [];
59→
60→  for (let guitarString = 1; guitarString <= 6; guitarString++) {
61→    const openNote = OPEN_STRING_NOTES[guitarString];
62→    const startIndex = CHROMATIC_SCALE.indexOf(openNote as typeof CHROMATIC_SCALE[number]);
63→
64→    for (let fret = 0; fret <= 15; fret++) {
65→      const noteIndex = (startIndex + fret) % 12;
66→      const noteName = CHROMATIC_SCALE[noteIndex];
67→
68→      if (NATURAL_NOTES.has(noteName)) {
69→        notes.push({
70→          string: guitarString,
71→          fret,
72→          note: noteName as NaturalNote,
73→          x: fretXPosition(fret),
74→          y: STRING_Y_POSITIONS[guitarString],
75→        });
76→      }
77→    }
78→  }
79→
80→  return notes;
81→}
82→
83→/** All natural notes (C, D, E, F, G, A, B) on frets 0-15, all 6 strings in standard tuning. */
84→export const FRET_NOTES: readonly FretNote[] = generateFretNotes();
85→

 1→import { Injectable } from '@angular/core';
 2→import { FretNote, FRET_NOTES } from './note-data';
 3→
 4→@Injectable({ providedIn: 'root' })
 5→export class NoteDataService {
 6→  getNotesInFretRange(minFret: number, maxFret: number): FretNote[] {
 7→    if (minFret > maxFret) {
 8→      return [];
 9→    }
10→    return FRET_NOTES.filter(note => note.fret >= minFret && note.fret <= maxFret);
11→  }
12→
13→  getNotesUpToFret(maxFret: number): FretNote[] {
14→    return this.getNotesInFretRange(0, maxFret);
15→  }
16→
17→  getNotesOnFret(fret: number): FretNote[] {
18→    return this.getNotesInFretRange(fret, fret);
19→  }
20→}
21→

 1→import { inject, Injectable } from '@angular/core';
 2→import { FretNote } from './note-data';
 3→import { NoteDataService } from './note-data.service';
 4→
 5→const MAX_FRET = 15;
 6→
 7→@Injectable()
 8→export class ProgressionService {
 9→  private readonly noteDataService = inject(NoteDataService);
10→
11→  private currentFret = 0;
12→  private pool: FretNote[] = [];
13→  private shownNoteKeys = new Set<string>();
14→
15→  constructor() {
16→    this.pool = this.noteDataService.getNotesOnFret(0);
17→  }
18→
19→  getCurrentPool(): FretNote[] {
20→    return this.pool;
21→  }
22→
23→  getCurrentFret(): number {
24→    return this.currentFret;
25→  }
26→
27→  getShownNoteCount(): number {
28→    return this.shownNoteKeys.size;
29→  }
30→
31→  drawNote(): FretNote {
32→    if (this.pool.length === 0) {
33→      throw new Error('ProgressionService: pool is empty — cannot draw note');
34→    }
35→    const index = Math.floor(Math.random() * this.pool.length);
36→    const note = this.pool[index];
37→    this.markNoteAsShown(note);
38→    return note;
39→  }
40→
41→  hasBeenShown(note: FretNote): boolean {
42→    return this.shownNoteKeys.has(this.noteKey(note));
43→  }
44→
45→  markNoteAsShown(note: FretNote): void {
46→    this.shownNoteKeys.add(this.noteKey(note));
47→
48→    if (this.shownNoteKeys.size >= this.pool.length) {
49→      this.expandPool();
50→    }
51→  }
52→
53→  reset(): void {
54→    this.currentFret = 0;
55→    this.pool = this.noteDataService.getNotesOnFret(0);
56→    this.shownNoteKeys.clear();
57→  }
58→
59→  private expandPool(): void {
60→    let nextFret = this.currentFret + 1;
61→
62→    while (nextFret <= MAX_FRET) {
63→      const newNotes = this.noteDataService.getNotesOnFret(nextFret);
64→      if (newNotes.length > 0) {
65→        this.currentFret = nextFret;
66→        this.pool = this.noteDataService.getNotesUpToFret(nextFret);
67→        this.shownNoteKeys.clear();
68→        return;
69→      }
70→      nextFret++;
71→    }
72→
73→    // Already at max — reset shown tracking so the game continues cycling
74→    this.shownNoteKeys.clear();
75→  }
76→
77→  private noteKey(note: FretNote): string {
78→    return `${note.string}-${note.fret}`;
79→  }
80→}
