  1→import { TestBed } from '@angular/core/testing';
  2→import { NoteDataService } from './note-data.service';
  3→import { FretNote, FRET_NOTES } from './note-data';
  4→
  5→describe('NoteDataService', () => {
  6→  let service: NoteDataService;
  7→
  8→  beforeEach(() => {
  9→    TestBed.configureTestingModule({});
 10→    service = TestBed.inject(NoteDataService);
 11→  });
 12→
 13→  describe('getNotesInFretRange', () => {
 14→    it('should return only open string notes when range is 0-0', () => {
 15→      const result = service.getNotesInFretRange(0, 0);
 16→
 17→      expect(result.length).toBe(6);
 18→      for (const note of result) {
 19→        expect(note.fret).toBe(0);
 20→      }
 21→    });
 22→
 23→    it('should return notes within frets 0-3', () => {
 24→      const result = service.getNotesInFretRange(0, 3);
 25→
 26→      for (const note of result) {
 27→        expect(note.fret).toBeGreaterThanOrEqual(0);
 28→        expect(note.fret).toBeLessThanOrEqual(3);
 29→      }
 30→      // Should include open strings plus fret 1-3 natural notes
 31→      expect(result.length).toBeGreaterThan(6);
 32→    });
 33→
 34→    it('should return notes within frets 0-5', () => {
 35→      const result = service.getNotesInFretRange(0, 5);
 36→
 37→      for (const note of result) {
 38→        expect(note.fret).toBeGreaterThanOrEqual(0);
 39→        expect(note.fret).toBeLessThanOrEqual(5);
 40→      }
 41→      expect(result.length).toBeGreaterThan(0);
 42→    });
 43→
 44→    it('should return all notes when range is 0-15', () => {
 45→      const result = service.getNotesInFretRange(0, 15);
 46→
 47→      expect(result.length).toBe(FRET_NOTES.length);
 48→    });
 49→
 50→    it('should return notes only in frets 5-10', () => {
 51→      const result = service.getNotesInFretRange(5, 10);
 52→
 53→      for (const note of result) {
 54→        expect(note.fret).toBeGreaterThanOrEqual(5);
 55→        expect(note.fret).toBeLessThanOrEqual(10);
 56→      }
 57→      expect(result.length).toBeGreaterThan(0);
 58→    });
 59→
 60→    it('should return an empty array when minFret exceeds maxFret', () => {
 61→      const result = service.getNotesInFretRange(10, 5);
 62→
 63→      expect(result).toEqual([]);
 64→    });
 65→
 66→    it('should return an empty array when range is outside valid frets', () => {
 67→      const result = service.getNotesInFretRange(16, 20);
 68→
 69→      expect(result).toEqual([]);
 70→    });
 71→
 72→    it('should return the correct natural notes for frets 2-4 based on guitar theory', () => {
 73→      const result = service.getNotesInFretRange(2, 4);
 74→
 75→      // In standard tuning (E-A-D-G-B-E), natural notes on frets 2-4:
 76→      // Fret 2: string 3 = A, string 4 = E, string 5 = B
 77→      // Fret 3: string 1 = G, string 2 = D, string 4 = F, string 5 = C, string 6 = G
 78→      // Fret 4: string 3 = B
 79→      expect(result.length).toBe(9);
 80→
 81→      const noteMap = result.map(note => ({ s: note.string, f: note.fret, n: note.note }));
 82→      expect(noteMap).toContainEqual({ s: 3, f: 2, n: 'A' });
 83→      expect(noteMap).toContainEqual({ s: 4, f: 2, n: 'E' });
 84→      expect(noteMap).toContainEqual({ s: 5, f: 2, n: 'B' });
 85→      expect(noteMap).toContainEqual({ s: 1, f: 3, n: 'G' });
 86→      expect(noteMap).toContainEqual({ s: 2, f: 3, n: 'D' });
 87→      expect(noteMap).toContainEqual({ s: 4, f: 3, n: 'F' });
 88→      expect(noteMap).toContainEqual({ s: 5, f: 3, n: 'C' });
 89→      expect(noteMap).toContainEqual({ s: 6, f: 3, n: 'G' });
 90→      expect(noteMap).toContainEqual({ s: 3, f: 4, n: 'B' });
 91→    });
 92→
 93→    it('should include correct open string notes in standard tuning for range 0-0', () => {
 94→      const result = service.getNotesInFretRange(0, 0);
 95→      const noteMap = new Map(result.map((note: FretNote) => [note.string, note.note]));
 96→
 97→      expect(noteMap.get(6)).toBe('E');
 98→      expect(noteMap.get(5)).toBe('A');
 99→      expect(noteMap.get(4)).toBe('D');
100→      expect(noteMap.get(3)).toBe('G');
101→      expect(noteMap.get(2)).toBe('B');
102→      expect(noteMap.get(1)).toBe('E');
103→    });
104→  });
105→
106→  describe('getNotesUpToFret', () => {
107→    it('should return all notes from fret 0 up to the given fret', () => {
108→      const result = service.getNotesUpToFret(5);
109→
110→      for (const note of result) {
111→        expect(note.fret).toBeGreaterThanOrEqual(0);
112→        expect(note.fret).toBeLessThanOrEqual(5);
113→      }
114→      expect(result.length).toBeGreaterThan(0);
115→    });
116→
117→    it('should return only open strings for fret 0', () => {
118→      const result = service.getNotesUpToFret(0);
119→
120→      expect(result.length).toBe(6);
121→      for (const note of result) {
122→        expect(note.fret).toBe(0);
