 1→import { inject, Injectable } from '@angular/core';
 2→import { FretNote } from './note-data';
 3→import { NoteDataService } from './note-data.service';
 4→
 5→const MAX_FRET = 15;
 6→
 7→@Injectable()
 8→export class ProgressionService {
 9→  private readonly noteDataService = inject(NoteDataService);
10→
11→  private currentFret = 0;
12→  private pool: FretNote[] = [];
13→  private shownNoteKeys = new Set<string>();
14→
15→  constructor() {
16→    this.pool = this.noteDataService.getNotesOnFret(0);
17→  }
18→
19→  getCurrentPool(): FretNote[] {
20→    return this.pool;
21→  }
22→
23→  getCurrentFret(): number {
24→    return this.currentFret;
25→  }
26→
27→  getShownNoteCount(): number {
28→    return this.shownNoteKeys.size;
29→  }
30→
31→  drawNote(): FretNote {
32→    if (this.pool.length === 0) {
33→      throw new Error('ProgressionService: pool is empty — cannot draw note');
34→    }
35→    const index = Math.floor(Math.random() * this.pool.length);
36→    const note = this.pool[index];
37→    this.markNoteAsShown(note);
38→    return note;
39→  }
40→
41→  hasBeenShown(note: FretNote): boolean {
42→    return this.shownNoteKeys.has(this.noteKey(note));
43→  }
44→
45→  markNoteAsShown(note: FretNote): void {
46→    this.shownNoteKeys.add(this.noteKey(note));
47→
48→    if (this.shownNoteKeys.size >= this.pool.length) {
49→      this.expandPool();
50→    }
51→  }
52→
53→  reset(): void {
54→    this.currentFret = 0;
55→    this.pool = this.noteDataService.getNotesOnFret(0);
56→    this.shownNoteKeys.clear();
57→  }
58→
59→  private expandPool(): void {
60→    let nextFret = this.currentFret + 1;
61→
62→    while (nextFret <= MAX_FRET) {
63→      const newNotes = this.noteDataService.getNotesOnFret(nextFret);
64→      if (newNotes.length > 0) {
65→        this.currentFret = nextFret;
66→        this.pool = this.noteDataService.getNotesUpToFret(nextFret);
67→        this.shownNoteKeys.clear();
68→        return;
69→      }
70→      nextFret++;
71→    }
72→
73→    // Already at max — reset shown tracking so the game continues cycling
74→    this.shownNoteKeys.clear();
75→  }
76→
77→  private noteKey(note: FretNote): string {
78→    return `${note.string}-${note.fret}`;
79→  }
80→}
